from __future__ import annotations
from abc_creative_gold_v5_101_200_support import make_spec, register_craft
FACTS={
"Apron":"Protective garment covers clothing during cooking/craft/cleaning; it does not replace handwashing or safe tool use.","Bath":"Washing body in tub/shower; young children need close adult supervision around water and safe water temperature.","Comb":"Toothed grooming tool separates/arranges hair; clean personal combs reduce sharing of scalp contaminants.","Door":"Movable barrier opens/closes a passage; hinge and closing edge are pinch points.","Eggs":"Food with shell, white, and yolk; raw/undercooked egg can carry pathogens, so hygiene and cooking guidance matter.","Fork":"Tined eating utensil; use seated/calmly and choose age-appropriate size.","Getting-dressed Chart":"Visual sequence supports remembering clothing steps; it is a prompt, not a rule that every outfit uses every item.","Hairbrush":"Bristled/pinned grooming tool detangles/styles hair; gentle technique avoids pulling and personal brushes should stay clean.","Indoor Shoes":"Footwear reserved for indoor surfaces; helps separate outdoor dirt and may support household/school routines.","Jacket":"Outer layer adds warmth/weather protection depending material; choose it for conditions, not simply because it appears on a chart.","Kettle":"Appliance/vessel heats water; boiling water, steam, and hot surfaces are adult-only.","Lunchbox":"Container carries a meal/snack; food temperature and hygiene depend on contents and storage.","Morning Chart":"Visual routine prompt lists morning tasks in an order that can be adapted to the household.","Nightlight":"Low-level light aids orientation at night; outlet/cord placement remains an electrical safety issue.","Oatmeal":"Cooked oat cereal absorbs liquid and thickens; it can stay very hot after cooking, so temperature is checked before eating.","Pajamas":"Sleepwear designed for comfort; fabric/fit and sleep-safety guidance vary by age.","Quiet Book":"Soft/activity or reading book for calm independent/shared use; quiet is an option, not a punishment.","Routine Chart":"Visual list helps remember repeated tasks; routines can flex when needs or schedules change.","Soap":"Cleaning substance helps water remove oils/dirt; avoid eyes/mouth and use the product intended for the task.","Toothbrush":"Brush cleans tooth surfaces with toothpaste/water as appropriate; it is personal and should not be shared.","Utensils":"General word for eating/prep tools; exact safety depends on whether the utensil is a spoon, knife, fork, etc.","Vacuum":"Powered cleaning appliance removes debris by airflow; cords/electricity/moving brush require adult or supervised use.","Washcloth":"Small absorbent cloth supports washing skin/surfaces; use clean cloth and appropriate soap/water.","Xylophone":"Tuned-bar musical instrument; deliberate routine-set comparison item, not a required morning chore.","Yawn":"Involuntary behavior associated with sleepiness and changes in alertness; a yawn alone does not prove bedtime or illness.","Zip Pajamas":"Pajamas closed with a zipper; slider/fabric can catch, so zip slowly and ensure comfortable fit.","Alarm Clock":"Timepiece can signal a planned wake/event time; an alarm does not measure whether someone got enough sleep.","Bed":"Furniture supports sleep/rest; age-appropriate safe sleep setup matters, especially for infants/young children.","Evening Book":"Book used during an evening routine; reading can cue transition without guaranteeing sleep.","Face Towel":"Small towel dries face; personal clean towels reduce cross-contamination and eye irritation.","Glass":"Drinking vessel can be breakable; age/material/context determine whether an adult should handle it.","Ice Water":"Cold drinking water with ice; small hard ice pieces can be choking risks for young children.","Juice":"Drink made from fruit/vegetable juice; amount, added sugar, and dental context matter, and water is still a core hydration drink.","Key":"Lock-opening object; small keys can be choking hazards and access keys stay with responsible users.","Lamp":"Electrical light source; stable placement, hot bulbs, cords, and outlets need safe setup.","Milk":"Nutrient-containing drink/food; type and suitability depend on age, allergies/intolerance, diet, and household guidance.","Outfit":"Set of clothes worn together; choice can reflect weather, activity, comfort, culture, or preference.","Plate":"Flat dish holds food; material and food temperature determine safe handling.","Robe":"Loose garment worn over sleepwear/clothes; belts/loose fabric need snag awareness.","Uniform":"Standardized clothing for school/work/team; it identifies context but not a person's ability or worth.","Vitamins":"Micronutrients needed in small amounts; supplements are not candy and should only be given by responsible adults according to need/guidance.","X-shaped Timer":"Project timer with X-like visual form; a timer shows elapsed/remaining time but cannot decide readiness by itself.","Cup":"Small open drinking/measure container; exact role depends on context.","Dinner":"Evening/main meal in many routines; timing, foods, and family structure vary widely.","Hand Soap":"Soap formulated for handwashing; lather/rinse helps remove dirt and microbes when used properly.","Napkin":"Cloth/paper wipes hands/mouth during meals; it does not replace handwashing when cleaning is needed.","Quilt":"Layered stitched textile provides warmth; sleep suitability depends on age and context.","Towel":"Absorbent textile dries skin/surfaces; wet towels should dry rather than stay on floor.","Water Bottle":"Personal container carries drinking water; keeping it clean and not sharing mouthpieces supports hygiene.","Yogurt":"Fermented dairy food or plant-based analogue depending product; label reveals ingredients/allergens and refrigeration needs.","Zipper":"Interlocking teeth/slider closes clothing/bags; move slowly to avoid catching skin or fabric.","Slippers":"Soft indoor footwear; traction and fit matter, especially on stairs or smooth floors.",
}
ACTIONS={"Bath":"Point to bath picture; say close adult supervision—no water-play mime.","Kettle":"Point only; hot adult appliance.","Vacuum":"Point only; powered tool stays adult/supervised.","Vitamins":"Point only; say adult gives correct dose—never candy play.","Glass":"Point; say breakable if the pictured vessel is glass.","Ice Water":"Point; no pretend ice swallowing.","Toothbrush":"Mime brushing your own teeth with an empty finger; no sharing.","Key":"Point; keep real access keys with responsible adults.","Lamp":"Point; no outlet/cord touching mime.","Door":"Open/close two palms slowly; keep fingers away from hinge edge.","Robe":"Point; no belt wrapping around body."}
